#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32

__global__ void matmul_kernel_shared_mem(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_DIM][TILE_DIM];
    __shared__ float Bs[TILE_DIM][TILE_DIM];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE_DIM + ty;
    int col = bx * TILE_DIM + tx;

    float Cvalue = 0.0f;

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tiles of A and B from global memory to shared memory
        if (row < N && (t * TILE_DIM + tx) < N) {
            As[ty][tx] = A[row * N + t * TILE_DIM + tx];
        } else {
            As[ty][tx] = 0.0f;
        }

        if ((t * TILE_DIM + ty) < N && col < N) {
            Bs[ty][tx] = B[(t * TILE_DIM + ty) * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Multiply tiles from shared memory
        for (int k = 0; k < TILE_DIM; ++k) {
            Cvalue += As[ty][k] * Bs[k][tx];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = Cvalue;
    }
}

