#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define WORK_PER_THREAD 4

__global__ void matmul_kernel_fixed(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_DIM][TILE_DIM];
    __shared__ float Bs[TILE_DIM][TILE_DIM];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int row = by * TILE_DIM + ty;
    int col_start = bx * TILE_DIM;

    float Cvals[WORK_PER_THREAD] = {0.0f};

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tile of A
        if (row < N && (t * TILE_DIM + tx) < N) {
            As[ty][tx] = A[row * N + t * TILE_DIM + tx];
        } else {
            As[ty][tx] = 0.0f;
        }

        // Load tile of B
        int b_col = col_start + tx;
        int b_row = t * TILE_DIM + ty;
        if (b_row < N && b_col < N) {
            Bs[ty][tx] = B[b_row * N + b_col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        for (int k = 0; k < TILE_DIM; ++k) {
            float a_val = As[ty][k];
            for (int w = 0; w < WORK_PER_THREAD; ++w) {
                int b_idx = tx + w * (TILE_DIM / WORK_PER_THREAD);
                if(b_idx < TILE_DIM) {
                    Cvals[w] += a_val * Bs[k][b_idx];
                }
            }
        }

        __syncthreads();
    }

    for (int w = 0; w < WORK_PER_THREAD; ++w) {
        int c_col = col_start + tx + w * (TILE_DIM/WORK_PER_THREAD);
        if (row < N && c_col < N) {
            C[row * N + c_col] = Cvals[w];
        }
    }
}

